using System.ComponentModel;
using System.Windows.Controls;

namespace Wpf.Zen.Ui.Controls;

/// <summary>
/// Defines context-menu styles and makes the implicit <see cref="ContextMenu"/> style available
/// to the default menus generated by WPF text editors.
/// </summary>
/// <remarks>
/// Load Controls/ContextMenu/ContextMenu.xaml through a resource URI. The XAML loader populates
/// this dictionary and registers the editor style synchronously at the end of initialization.
/// The dictionary must be in the menu's resource lookup scope for the implicit style to apply.
/// If WPF no longer exposes the expected internal type, ordinary context-menu styles remain usable
/// and the editor menu retains its WPF default appearance.
/// </remarks>
public partial class ContextMenuResources : ResourceDictionary, ISupportInitialize
{
    private static readonly Type? EditorContextMenuType = GetEditorContextMenuType();

    // ResourceDictionary's initialization methods are not virtual. Reimplement the interface
    // used by the XAML loader so registration runs after deferred resource keys are available,
    // but before EndInit notifies resource owners. Do not call InitializeComponent from a
    // constructor: ResourceDictionary.Source is already loading this instance's BAML.
    void ISupportInitialize.BeginInit() => BeginInit();

    void ISupportInitialize.EndInit()
    {
        RegisterEditorContextMenuStyle();
        EndInit();
    }

    /// <summary>
    /// Shares the ordinary implicit style with the exact runtime type used by WPF's editor menus.
    /// </summary>
    private void RegisterEditorContextMenuStyle()
    {
        // Implicit Style lookup uses GetType(), not DefaultStyleKey, and does not walk base types.
        // A resource key may name a derived type while its Style still targets ContextMenu.
        // Use the public type key so this code does not depend on the named base style's XAML key.
        if (EditorContextMenuType is { } editorType && this[typeof(ContextMenu)] is Style style)
        {
            this[editorType] = style;
        }
    }

    /// <summary>
    /// Resolves the private editor-menu type once without requiring access to menu instances.
    /// </summary>
    private static Type? GetEditorContextMenuType()
    {
        // WPF offers no public type or resource key for its automatically generated editor menu.
        // Only its identity is reflected; no internal state or theme cache is modified. Missing
        // or incompatible types disable the alias and leave WPF's theme-style fallback intact.
        try
        {
            Type? type = typeof(ContextMenu).Assembly.GetType(
                "System.Windows.Documents.TextEditorContextMenu+EditorContextMenu",
                throwOnError: false
            );

            return type is not null && typeof(ContextMenu).IsAssignableFrom(type) ? type : null;
        }
        catch (TypeLoadException)
        {
            return null;
        }
    }
}
